const s=$json.state||{};
const allowed=['NEW','BROWSING','DISCOVERY','PRODUCT_INTEREST','CONSIDERING','OBJECTION_HANDLING','PRODUCT_SELECTED','CART_BUILDING','CHECKOUT_READY','PURCHASED','POST_PURCHASE','CLOSED','WAITING_FOR_CUSTOMER','HUMAN_ESCALATION'];
const stage=allowed.includes(s.stage)?s.stage:'NEW';
const intent=$json.intent;
const salesIntents=['product_discovery','product_question','comparison','pricing','promotion','availability','cart_view','cart_add','cart_remove','cart_update','cart_clear','checkout_start','checkout_confirm'];
return [{json:{...$json,sales_stage:stage,is_sales_intent:salesIntents.includes(intent),sales_intents:salesIntents}}];

const t=String($json.text||'').normalize('NFKC').trim();
const lower=t.toLocaleLowerCase();
const extract={
  size:(lower.match(/(?:taille|size)\s*(?:=|:)?\s*(xs|s|m|l|xl|xxl|\d{2})/i)||[])[1]||null,
  quantity:(lower.match(/(?:x|qty|quantit[eé]|quantite)\s*(\d+)/i)||[])[1]?Number((lower.match(/(?:x|qty|quantit[eé]|quantite)\s*(\d+)/i)||[])[1]):null
};
const hasProductRef=Boolean($json.state?.selected_product_id||$json.selected_product_id||/\b(ce|cette|hedha|hedhi|this|that|produit|article|model)\b/i.test(lower));
return [{json:{...$json,customer_text:t,extracted:extract,has_product_reference:hasProductRef}}];

const intent=$json.intent;
const stage=$json.sales_stage;
let next=stage;
let action='answer';
let needs_clarification=false;
let reason='';

if(intent==='product_discovery'){next=['NEW','BROWSING'].includes(stage)?'DISCOVERY':'PRODUCT_INTEREST';}
else if(['product_question','comparison','pricing','promotion','availability'].includes(intent)){next='CONSIDERING';}
else if(intent==='cart_view'){next='CART_BUILDING'; action='cart_view';}
else if(intent==='cart_add'){next='CART_BUILDING'; action='cart_add';}
else if(intent==='cart_remove'){next='CART_BUILDING'; action='cart_remove';}
else if(intent==='cart_update'){next='CART_BUILDING'; action='cart_update';}
else if(intent==='cart_clear'){next='CART_BUILDING'; action='cart_clear';}
else if(intent==='checkout_start'){next='CHECKOUT_READY'; action='checkout_start';}
else if(intent==='checkout_confirm'){next='CHECKOUT_READY'; action='checkout_confirm';}

if(['cart_add','cart_remove','cart_update'].includes(intent) && !$json.has_product_reference && !$json.state?.cart_id){
  needs_clarification=true;
  reason='missing_product_or_cart_context';
}
return [{json:{...$json,next_sales_stage:next,proposed_sales_action:action,needs_clarification,reason}}];

const intent=$json.intent;
const requiresTool=['availability','pricing','promotion','cart_view','cart_add','cart_remove','cart_update','cart_clear','checkout_start','checkout_confirm'].includes(intent);
const discovery=['product_discovery','product_question','comparison'].includes(intent);
return [{json:{...$json,
  route:'sales',
  llm_allowed:true,
  tools_allowed:requiresTool,
  retrieval_required:discovery||requiresTool,
  execution_allowed:false,
  action_proposal_allowed:['cart_add','cart_remove','cart_update','cart_clear','checkout_start','checkout_confirm'].includes(intent)
}}];
